 ('otp_request','OTP Request',35,'high'),('pin_request','PIN Request',45,'critical'),('password_request','Password Request',35,'high'),('urgency','Urgency',10,'medium'),('fear_or_threat','Fear or Threat',18,'high'),('advance_payment','Advance Payment',25,'high'),('guaranteed_return','Guaranteed Return',25,'high'),('suspicious_domain','Suspicious URL',25,'high'),('impersonation','Impersonation',25,'high'),('remote_access_request','Remote Access Request',40,'critical') on conflict (key) do nothing;
